    constructor(C _c) {
        c = _c;
    }

    function run(
        address dao,
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable,
        address targetContract,
        address user
    ) public payable {
        require(dao != address(0), "dao zero");
        require(asset != address(0), "asset zero");
        require(targetContract != address(0), "target zero");
        require(user != address(0), "user zero");

        c.setDAO(dao);

        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        (
            uint256 storedAmount,
            uint256 storedUnlockTime,
            address storedAsset,
            bool storedBurnable
        ) = c.flashGovernanceConfig();

        assert(
            storedAsset == asset &&
                storedAmount == amount &&
                storedUnlockTime == unlockTime &&
                storedBurnable == assetBurnable
        );
    }
}

