contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address[] calldata governables,
        bool[] calldata isGoverned,
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable,
        address target,
        address sender,
        bool emergency
    ) public payable {
        require(governables.length == isGoverned.length, "length mismatch");

        // fresh c: unconfigured and no governance asset configured
        assert(!c.configured());
        assert(c.flashGovernanceConfig.asset() == address(0));

        // Any non-DAO, non-governed caller must be rejected by flashEnabled modifier.
        bool revertedBeforeGoverned;
        try c.assertGovernanceApproved(sender, target, emergency) {
            revertedBeforeGoverned = false;
        } catch {
            revertedBeforeGoverned = true;
        }

        // configure flash governance directly (onlySuccessfulProposal: DAO is c.DAO and successfulProposal is false, so this call reverts)
        // Instead, use setGoverned, which is also onlySuccessfulProposal and should revert for non-successful proposal.
        bool revertedSetGoverned;
        try c.setGoverned(governables, isGoverned) {
            revertedSetGoverned = false;
        } catch {
            revertedSetGoverned = true;
        }

        // Because no successful proposal has been made, setGoverned must revert,
        // so the governed mapping must remain unchanged (all false) for every input.
        for (uint256 i = 0; i < governables.length; i++) {
            assert(!c.governed(governables[i]));
        }

        // And assertGovernanceApproved must also revert for an ungoverned sender
        // (the onlySoulUpdateProposal / flashEnabled path requires DAO or governed).
        if (sender != address(0)) {
            assert(revertedBeforeGoverned);
        }

        // The assert below is the general rule that ties the observed revert behavior:
        // since no successful proposal exists, both governance-gated state changes must fail.
        assert(revertedSetGoverned && (sender == address(0) || revertedBeforeGoverned));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address[] calldata governables,
        bool[] calldata isGoverned,
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable,
        address sender,
        address target,
        bool emergency
    ) public payable {
        require(governables.length == isGoverned.length, "length mismatch");

        bool revertedSetGoverned;
        try c.setGoverned(governables, isGoverned) {
            revertedSetGoverned = false;
        } catch {
            revertedSetGoverned = true;
        }

        bool revertedConfigureFlash;
        try c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable) {
            revertedConfigureFlash = false;
        } catch {
            revertedConfigureFlash = true;
        }

        bool revertedAssertApproved;
        try c.assertGovernanceApproved(sender, target, emergency) {
            revertedAssertApproved = false;
        } catch {
            revertedAssertApproved = true;
        }

        for (uint256 i = 0; i < governables.length; i++) {
            assert(!c.governed(governables[i]));
        }

        (, , address configAsset, ) = c.flashGovernanceConfig();
        assert(configAsset == address(0));

        assert(revertedSetGoverned && revertedConfigureFlash && revertedAssertApproved);
    }

    receive() external payable {}
}

