contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address asset,
        uint256 amount,
        uint256 unlockTime,
        address targetContract,
        address user,
        address assetForWithdraw
    ) public payable {
        // Nothing pre-existing to require on c's state: fresh deployment.

        // Setup: configure flash governance so pending decisions can exist.
        // onlySuccessfulProposal: if c is not configured, any sender passes.
        c.configureFlashGovernance(asset, amount, unlockTime, false);

        // Drive a governance decision that places a pending entry for (targetContract, user).
        // msg.sender to c is this InvMutTest contract (flashEnabled check: DAO or governed).
        // We try to make it succeed; if it reverts we don't need to require, the state stays empty.
        bool decisionOk;
        try c.assertGovernanceApproved(user, targetContract, true) {
            decisionOk = true;
        } catch {
            decisionOk = false;
        }

        // Read the pending config for the caller (this contract) on the pending entry keyed by targetContract.
        uint256 pendingAmount;
        uint256 pendingUnlockTime;
        address pendingAsset;
        (pendingAmount, pendingUnlockTime, pendingAsset, ) = c.pendingFlashDecision(targetContract, user);

        // The withdraw call: caller is this contract, pending key is (targetContract, msg.sender = this).
        // For a successful call we need pending entry with asset == assetForWithdraw, amount > 0, unlockTime < now.
        // We do not force it; observe whether it reverts.
        bool withdrawReverted;
        try c.withdrawGovernanceAsset(targetContract, assetForWithdraw) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // After the call, read the pending entry again (this contract is the sender/owner of the entry).
        uint256 afterAmount;
        uint256 afterUnlockTime;
        address afterAsset;
        (afterAmount, afterUnlockTime, afterAsset, ) = c.pendingFlashDecision(targetContract, user);

        // General rule: whenever withdrawGovernanceAsset did not revert, the pending decision for
        // the caller was cleared: all fields are zero/default after the call.
        // (The caller of withdrawGovernanceAsset is this contract, and pendingFlashDecision is keyed
        //  by targetContract and msg.sender; the entry for `user` may still exist, but the caller's
        //  entry for `targetContract` must be cleared.)
        // We assert about the entry for the user only when user == address(this), because withdraw
        // clears pendingFlashDecision[targetContract][msg.sender]; when user != address(this) the
        // entry for `user` may be untouched. The observable cleared entry is the one for msg.sender.
        // Read the caller's pending entry before and after.
        uint256 callerBeforeAmount;
        uint256 callerBeforeUnlock;
        address callerBeforeAsset;
        (callerBeforeAmount, callerBeforeUnlock, callerBeforeAsset, ) = c.pendingFlashDecision(targetContract, address(this));

        assert(
            withdrawReverted ||
            (callerBeforeAmount == 0 &&
                callerBeforeUnlock == 0 &&
                callerBeforeAsset == address(0) &&
                afterAmount == 0 &&
                afterUnlockTime == 0 &&
                afterAsset == address(0) &&
                pendingAmount == afterAmount &&
                pendingUnlockTime == afterUnlockTime &&
                pendingAsset == afterAsset)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint8 maxGovernanceChangePerEpoch, uint256 epochSize, uint8 changeTolerance) public {
        bool reverted;
        try c.configureSecurityParameters(maxGovernanceChangePerEpoch, epochSize, changeTolerance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 storedEpochSize, uint256 storedLastFlashGovernanceAct, uint8 storedMaxGovernanceChangePerEpoch, uint8 storedChangeTolerance) = c.security();

        assert(
            (reverted && changeTolerance >= 100) ||
            (!reverted && storedEpochSize == epochSize && storedLastFlashGovernanceAct == 0 && storedMaxGovernanceChangePerEpoch == maxGovernanceChangePerEpoch && storedChangeTolerance == changeTolerance)
        );
    }

    receive() external payable {}
}

