            (!reverted && changeTolerance < 100 && storedEpochSize == epochSize && storedLastFlashGovernanceAct == 0 && storedMaxGovernanceChangePerEpoch == maxGovernanceChangePerEpoch && storedChangeTolerance == changeTolerance)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint8 maxGovernanceChangePerEpoch, uint256 epochSize, uint8 changeTolerance) public {
        (uint256 oldEpochSize, uint256 oldLastAct, uint8 oldMaxChange, uint8 oldTolerance) = c.security();
        bool reverted;
        try c.configureSecurityParameters(maxGovernanceChangePerEpoch, epochSize, changeTolerance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 newEpochSize, uint256 newLastAct, uint8 newMaxChange, uint8 newTolerance) = c.security();

        if (reverted) {
            assert(
                changeTolerance >= 100 &&
                newEpochSize == oldEpochSize &&
                newLastAct == oldLastAct &&
                newMaxChange == oldMaxChange &&
                newTolerance == oldTolerance
            );
        } else {
            assert(
                changeTolerance < 100 &&
                newEpochSize == epochSize &&
                newLastAct == oldLastAct &&
                newMaxChange == maxGovernanceChangePerEpoch &&
                newTolerance == changeTolerance
            );
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint8 maxGovernanceChangePerEpoch, uint256 epochSize, uint8 changeTolerance) public {
        (uint256 oldEpochSize, uint256 oldLastAct, uint8 oldMaxChange, uint8 oldTolerance) = c.security();

        bool reverted;
        try c.configureSecurityParameters(maxGovernanceChangePerEpoch, epochSize, changeTolerance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 newEpochSize, uint256 newLastAct, uint8 newMaxChange, uint8 newTolerance) = c.security();

        assert(
            reverted == (changeTolerance >= 100) &&
            (reverted
                ? (newEpochSize == oldEpochSize && newLastAct == oldLastAct && newMaxChange == oldMaxChange && newTolerance == oldTolerance)
                : (newEpochSize == epochSize && newMaxChange == maxGovernanceChangePerEpoch && newTolerance == changeTolerance))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 amount, uint256 unlockTime, bool assetBurnable, uint8 maxChange, uint256 epochSize, uint8 tolerance) public {
        c.configureFlashGovernance(address(0xdead), amount, unlockTime, assetBurnable);
        c.configureSecurityParameters(maxChange, epochSize, tolerance);

        (uint256 fgAmount, uint256 fgUnlock, address fgAsset, bool fgBurnable) = c.flashGovernanceConfig();
        (uint256 secEpoch, uint256 secLast, uint8 secMax, uint8 secTol) = c.security();

        bool maxOk = secMax == maxChange || secMax == 0;
        bool tolOk = secTol == tolerance || secTol == 0;
        bool epochOk = secEpoch == epochSize || secEpoch == 0;

        assert(
            fgAmount == amount &&
            fgUnlock == unlockTime &&
            fgAsset == address(0xdead) &&
            fgBurnable == assetBurnable &&
            epochOk &&
            maxOk &&
            tolOk
        );
    }

    receive() external payable {}
}

