contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address target, address asset, uint256 amount, uint256 unlockTime, bool assetBurnable) public payable {
        // The contract caller must be the DAO to configure flash governance (onlySuccessfulProposal gate bypassed only when !configured).
        // Since we cannot set configured, we rely on configured == false initially, so configureFlashGovernance is callable by anyone.
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // Read back the configured pending struct before any decision
        (uint256 cfgAmount, uint256 cfgUnlock, address cfgAsset, bool cfgBurnable) = c.flashGovernanceConfig();

        // Try to create a pending flash governance decision for (target, sender). We cannot control msg.sender for the token transferFrom call outcome easily,
        // but we can still assert the general rule about withdraw governance asset independent of whether the pending entry exists or reverts.
        // We read the pending entry before and after withdraw attempt.
        (uint256 beforeAmount, uint256 beforeUnlock, address beforeAsset, bool beforeBurnable) = c.pendingFlashDecision(target, sender);

        bool reverted;
        try c.withdrawGovernanceAsset(target, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 afterAmount, uint256 afterUnlock, address afterAsset, bool afterBurnable) = c.pendingFlashDecision(target, sender);

        // General rule: If the pending entry for (target, msg.sender) had an asset matching the requested asset, positive amount,
        // and unlockTime < block.timestamp, then withdraw should succeed and clear the entry. Otherwise it must revert and leave the entry unchanged.
        // We assert the necessary consequence observable externally: after a successful withdraw, the pending entry must be deleted.
        if (!reverted) {
            assert(afterAmount == 0 && afterUnlock == 0 && afterAsset == address(0) && !afterBurnable);
        } else {
            // If it reverted, the pending entry must be unchanged relative to before.
            assert(beforeAmount == afterAmount && beforeUnlock == afterUnlock && beforeAsset == afterAsset && beforeBurnable == afterBurnable);
        }
        // Additionally, the configured flash governance parameters must remain exactly as set (not modified by withdraw).
        (uint256 finalAmount, uint256 finalUnlock, address finalAsset, bool finalBurnable) = c.flashGovernanceConfig();
        assert(finalAmount == amount && finalUnlock == unlockTime && finalAsset == asset && finalBurnable == assetBurnable);
    }

    receive() external payable {}
}

