        address asset
    ) public payable {
        // configure a flash governance decision for this contract as sender
        c.configureFlashGovernance(asset, amount, unlockTime, false);

        // ensure the asset is set
        (uint256 cfgAmount, uint256 cfgUnlock, address cfgAsset, bool cfgBurnable) = c.flashGovernanceConfig();
        require(cfgAmount == amount && cfgUnlock == unlockTime && cfgAsset == asset && cfgBurnable == false, "config not stored");

        // approve C to pull the asset amount from this contract
        require(IERC20_approve(asset, address(c), amount), "approve failed");

        // perform the governance approval, depositing the asset into C
        c.assertGovernanceApproved(address(this), targetContract, true);

        // read the pending decision for (targetContract, this)
        (uint256 pAmount, uint256 pUnlock, address pAsset, bool pBurnable) = c.pendingFlashDecision(targetContract, address(this));
        assert(pAmount == amount && pAsset == asset && pBurnable == false && pUnlock >= unlockTime, "pending decision not recorded as expected");

        // record balance before withdrawal
        uint256 balBefore = IERC20_balanceOf(asset, address(this));

        // withdraw the governance asset
        c.withdrawGovernanceAsset(targetContract, asset);

        // after withdrawal, pending decision is cleared and asset is returned
        (uint256 qAmount, , , ) = c.pendingFlashDecision(targetContract, address(this));
        uint256 balAfter = IERC20_balanceOf(asset, address(this));
        assert(qAmount == 0 && balAfter == balBefore + amount, "withdraw did not return asset or clear pending decision");

        // a second withdraw must revert because the pending decision was deleted
        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted, "second withdraw should revert after pending decision was cleared");
    }

    function IERC20_approve(address token, address spender, uint256 amount) internal returns (bool) {
        (bool ok, bytes memory data) = token.call(abi.encodeWithSignature("approve(address,uint256)", spender, amount));
        return ok && (data.length == 0 || abi.decode(data, (bool)));
    }

    function IERC20_balanceOf(address token, address account) internal view returns (uint256) {
        (bool ok, bytes memory data) = token.staticcall(abi.encodeWithSignature("balanceOf(address)", account));
        require(ok && data.length >= 32, "balanceOf failed");
        return abi.decode(data, (uint256));
    }

    receive() external payable {}
}

