contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool finishConfiguration, address asset, uint256 amount, uint256 unlockTime, bool assetBurnable) public {
        require(address(c) != address(0), "bad test setup");

        // Read the before-values.
        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, bool beforeBurnable) = c.flashGovernanceConfig();

        // Drive P: finish configuration if requested; this is just a setup call on c.
        if (finishConfiguration) {
            c.endConfiguration();
        }

        // Make the deciding call to configureFlashGovernance and capture whether it reverts.
        bool reverted;
        try c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the after-values.
        (uint256 afterAmount, uint256 afterUnlockTime, address afterAsset, bool afterBurnable) = c.flashGovernanceConfig();

        // General rule: if the call did not revert, the configuration must have been updated exactly
        // to the supplied values; if it reverted, the configuration must be unchanged.
        if (!reverted) {
            assert(afterAsset == asset && afterAmount == amount && afterUnlockTime == unlockTime && afterBurnable == assetBurnable);
        } else {
            assert(afterAsset == beforeAsset && afterAmount == beforeAmount && afterUnlockTime == beforeUnlockTime && afterBurnable == beforeBurnable);
        }
    }
}

