    }

    function run(
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable,
        address sender,
        address target,
        bool emergency
    ) public payable {
        require(amount > 0, "amount must be positive");
        require(asset != address(0), "asset must be non-zero");

        // A fresh, unminted mock ERC20-like asset is needed for the successful branch;
        // since we cannot deploy here, only test the rule when the configured asset
        // already has enough balance for c to transferFrom. We therefore set up the
        // governance configuration as the DAO (msg.sender of the test contract can
        // call this only when it is the DAO or already configured successfully).

        // First, record pre-state.
        address preAsset = c.flashGovernanceConfig().asset;
        uint256 preAmount = c.flashGovernanceConfig().amount;

        // Configure flash governance as the DAO (c was constructed with this test contract's address as dao).
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // Read back the configuration to check the setter's effect.
        address postAsset = c.flashGovernanceConfig().asset;
        uint256 postAmount = c.flashGovernanceConfig().amount;
        uint256 postUnlock = c.flashGovernanceConfig().unlockTime;
        bool postBurnable = c.flashGovernanceConfig().assetBurnable;

        // A rule that must hold regardless of the rest: configuration setter stores all four fields.
        bool configOk = (postAsset == asset) && (postAmount == amount) &&
                        (postUnlock == unlockTime) && (postBurnable == assetBurnable);

        // The general rule: for every input, after configureFlashGovernance the
        // public config getter reflects exactly the four inputs given.
        assert(configOk);
    }

    receive() external payable {}
}

