contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 epochSize, uint256 amount, uint256 unlockTime, bool assetBurnable, uint256 absorb) public {
        require(epochSize <= 1000000000);
        require(unlockTime > 0);
        require(absorb > 0);

        uint8 maxChange = 10;
        uint8 changeTol = 10;

        // Make this contract eligible to call flashEnabled functions.
        address[] memory govs = new address[](1);
        bool[] memory isGovs = new bool[](1);
        govs[0] = address(this);
        isGovs[0] = true;
        c.setGoverned(govs, isGovs);

        // Establish DAO as msg.sender by the return value of flashGoverner() being non-zero; instead we use the DAO setter.
        c.setDAO(address(this));

        // Configure flash governance for this contract.
        c.configureFlashGovernance(address(0x1234567890123456789012345678901234567890), amount, unlockTime, assetBurnable);

        // Configure security parameters so the epoch check and tolerance read are well-defined.
        c.configureSecurityParameters(maxChange, epochSize, changeTol);

        // No pending decision should exist for this caller yet.
        (uint256 pAmount0, uint256 pUnlock0, address pAsset0, bool pBurnable0) = c.pendingFlashDecision(address(c), address(this));
        require(pAmount0 == 0 && pUnlock0 == 0 && pAsset0 == address(0) && !pBurnable0);

        // Attempt the deciding call: assertGovernanceApproved with emergency=true so epoch check is bypassed.
        // The asset address is not a contract, so the transferFrom ERC20 call will revert, causing the whole call to revert.
        // Therefore we wrap it in try/catch to observe the rejection without aborting the test.
        bool assertReverted;
        try c.assertGovernanceApproved(address(this), address(c), true) {
            assertReverted = false;
        } catch {
            assertReverted = true;
        }

        // The general rule: because the configured flash governance asset is a plain address (not an ERC20), every
        // assertGovernanceApproved call must revert and must leave pendingFlashDecision untouched (zero).
        (uint256 pAmount1, uint256 pUnlock1, address pAsset1, bool pBurnable1) = c.pendingFlashDecision(address(c), address(this));
        assert(
            assertReverted &&
            pAmount1 == pAmount0 &&
            pUnlock1 == pUnlock0 &&
            pAsset1 == pAsset0 &&
            pBurnable1 == pBurnable0
        );
    }

    receive() external payable {}
}

