contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address targetContract, address user, uint256 amount, uint256 unlockTime, uint256 depositAmount) public payable {
        require(amount > 0, "precondition: amount must be positive for a meaningful withdrawal test");
        require(depositAmount >= amount, "precondition: deposit at least the recorded amount");
        require(address(this).balance >= depositAmount, "precondition: enough Ether to deposit");

        c.setGoverned(_toArray(address(this)), _toBoolArray(true));
        c.configureFlashGovernance(address(this), amount, unlockTime, false);

        bool approvedReverted = true;
        try c.assertGovernanceApproved(user, targetContract, true) {
            approvedReverted = false;
        } catch {
            approvedReverted = true;
        }

        bool withdrawalReverted;
        bool canWithdraw = !approvedReverted && unlockTime < block.timestamp;
        if (canWithdraw) {
            try c.withdrawGovernanceAsset(targetContract, address(this)) {
                withdrawalReverted = false;
            } catch {
                withdrawalReverted = true;
            }
        } else {
            withdrawalReverted = !approvedReverted || unlockTime >= block.timestamp;
        }

        assert(
            (approvedReverted && withdrawalReverted) ||
            (!approvedReverted && unlockTime >= block.timestamp && withdrawalReverted) ||
            (!approvedReverted && unlockTime < block.timestamp && !withdrawalReverted)
        );
    }

    function _toArray(address a) internal pure returns (address[] memory arr) {
        arr = new address[](1);
        arr[0] = a;
    }

    function _toBoolArray(bool b) internal pure returns (bool[] memory arr) {
        arr = new bool[](1);
        arr[0] = b;
    }

    receive() external payable {}
}

