contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address target, address asset, uint256 amount) public {
        require(sender != address(c) && target != address(c));
        require(sender != address(this));

        // Guarantee sender is not the DAO and not governed: if the current DAO is sender, pick another
        // DAO address by having the DAO be address(c) itself is not possible (c is not DAO here).
        // Observe c's public DAO getter; if it equals sender, we cannot make this call as ungoverned.
        // Ensure via precondition. We read DAO only after c exists.
        address dao = c.DAO();
        require(dao != sender);
        require(!c.governed(sender));

        // Before values of relevant public state.
        uint256 cAssetBefore = IERC20(asset).balanceOf(address(c));
        uint256 senderBefore = IERC20(asset).balanceOf(sender);

        // Try the call as sender; since sender is not DAO and not governed, it must revert.
        bool reverted;
        try c.assertGovernanceApproved(sender, target, false) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The call must revert because msg.sender (this contract) is not DAO and not governed:
        // flashEnabled requires msg.sender == DAO || governed[msg.sender].
        // Note: flashEnabled checks msg.sender, which is this InvMutTest contract, not `sender`.
        // So the call is ungoverned only if address(this) is not DAO and not governed.
        // Therefore require address(this) is not DAO and not governed.
        require(address(this) != dao);
        require(!c.governed(address(this)));

        // After values.
        uint256 cAssetAfter = IERC20(asset).balanceOf(address(c));
        uint256 senderAfter = IERC20(asset).balanceOf(sender);

        // General rule: unauthorized call reverts, balances unchanged.
        assert(reverted && cAssetAfter == cAssetBefore && senderAfter == senderBefore);
    }

    receive() external payable {}
}

