        assert(
            (caller != c.DAO() && !c.governed(caller))
                ? (reverted
                    && newAmount == oldAmount
                    && newUnlock == oldUnlock
                    && newAsset == oldAsset
                    && newBurnable == oldBurnable)
                : true
        );
    }

    receive() external payable {}
}

