    function run(address targetContract, address asset, uint256 amount, uint256 flashAmount, uint256 unlockTime) public {
        require(amount > 0);
        require(flashAmount >= amount);
        require(unlockTime < block.timestamp);

        // Snapshot the balance before setting up or withdrawing.
        uint256 balanceBefore = IERC20(asset).balanceOf(address(this));

        // Create a pending flash decision for msg.sender on targetContract.
        // Configure the asset as non-burnable so no burn happens during setup.
        c.configureFlashGovernance(asset, flashAmount, unlockTime, false);
        c.assertGovernanceApproved(address(this), targetContract, true);

        // The decision should now be withdrawable.
        c.withdrawGovernanceAsset(targetContract, asset);

        uint256 balanceAfter = IERC20(asset).balanceOf(address(this));
        (uint256 amt, , address a, ) = c.pendingFlashDecision(targetContract, address(this));

        // General rule: the withdraw sends out exactly the pending amount and clears the pending decision.
        assert(
            balanceAfter == balanceBefore + flashAmount &&
            amt == 0 &&
            a == address(0)
        );
    }
}

