contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address someAddr, address newGovernable, bool desired) public payable {
        require(someAddr != address(0), "zero");
        require(newGovernable != address(0), "zero");
        require(address(c) != someAddr, "cannot be contract itself as external caller");
        require(address(this) != someAddr, "caller must be external");

        // Try to become authorized. This should fail for arbitrary someAddr.
        bool setGovernedReverted;
        address[] memory a1 = new address[](1);
        bool[] memory b1 = new bool[](1);
        a1[0] = address(this);
        b1[0] = true;
        try c.setGoverned(a1, b1) {
            setGovernedReverted = false;
        } catch {
            setGovernedReverted = true;
        }

        // The call must have reverted for an unauthorized caller.
        // If it didn't, then address(this) is somehow authorized, which is impossible in a fresh deployment.
        assert(setGovernedReverted);

        // Since c's governed(address(this)) is false, any subsequent setGoverned from this
        // must also revert, and the flag for the target address must remain false.
        address[] memory a2 = new address[](1);
        bool[] memory b2 = new bool[](1);
        a2[0] = newGovernable;
        b2[0] = desired;

        bool secondReverted;
        try c.setGoverned(a2, b2) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        assert(secondReverted);
        assert(c.governed(newGovernable) == false);
    }
}

