    constructor(C _c) {
        c = _c;
    }

    function run(
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable,
        address target,
        address user,
        uint256 burnAmount
    ) public {
        // Configure flash governance via the successful-proposal path.
        // The DAO must recognize this test contract; in a fresh deployment this is the
        // only caller, so onlySuccessfulProposal is satisfied.
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // assertGovernanceApproved is flashEnabled: caller must be DAO or governed.
        // Since the test contract deployed c and is the DAO's recognized caller in the
        // harness, use it directly.
        c.assertGovernanceApproved(user, target, true);

        // Read the pending decision's stored asset before burning.
        address storedAssetBefore;
        uint256 storedAmountBefore;
        uint256 storedUnlockBefore;
        bool storedBurnableBefore;
        (storedAssetBefore, storedAmountBefore, storedUnlockBefore, storedBurnableBefore) =
            c.pendingFlashDecision(target, user);

        // The decision was accepted if the stored asset matches and amount is set.
        // Burn the pending governance asset. If not burnable, the function skips the
        // external burn call and simply deletes the pending decision.
        c.burnFlashGovernanceAsset(target, user, asset, burnAmount);

        // After burning, the pending decision is deleted: the getter must report a zero
        // amount and zero asset for this (target, user) pair.
        address storedAssetAfter;
        uint256 storedAmountAfter;
        uint256 storedUnlockAfter;
        bool storedBurnableAfter;
        (storedAssetAfter, storedAmountAfter, storedUnlockAfter, storedBurnableAfter) =
            c.pendingFlashDecision(target, user);

        assert(
            storedAmountAfter == 0 && storedAssetAfter == address(0)
        );
    }
}

