        uint256 burnAmount
    ) public {
        // Configure flash governance via the successful-proposal path.
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // The test contract is the deployer and thus the recognized DAO in a fresh harness,
        // and C's flashEnabled modifier allows the DAO caller.
        c.assertGovernanceApproved(user, target, true);

        // Read the pending decision's stored values before burning.
        // The public getter returns (uint256 amount, uint256 unlockTime, address asset, bool assetBurnable).
        uint256 storedAmountBefore;
        uint256 storedUnlockBefore;
        address storedAssetBefore;
        bool storedBurnableBefore;
        (storedAmountBefore, storedUnlockBefore, storedAssetBefore, storedBurnableBefore) =
            c.pendingFlashDecision(target, user);

        // Burn the pending governance asset. If not burnable, the external burn call is
        // skipped and the pending decision is simply deleted.
        c.burnFlashGovernanceAsset(target, user, asset, burnAmount);

        // After burning, the pending decision is deleted.
        uint256 storedAmountAfter;
        uint256 storedUnlockAfter;
        address storedAssetAfter;
        bool storedBurnableAfter;
        (storedAmountAfter, storedUnlockAfter, storedAssetAfter, storedBurnableAfter) =
            c.pendingFlashDecision(target, user);

        assert(
            storedAmountAfter == 0 && storedAssetAfter == address(0)
        );
    }
}

