        c = _c;
    }

    function run(address asset, uint256 amount, uint256 unlockTime, address target, address sender_, bool burnable) public payable {
        require(asset != address(0));
        require(amount > 0);

        // Setup governance config on c (requires DAO sender; test contract is DAO since it deployed c)
        c.configureFlashGovernance(asset, amount, unlockTime, burnable);

        uint256 cBefore = IERC20(asset).balanceOf(address(c));
        uint256 thisBefore = IERC20(asset).balanceOf(address(this));

        // Fund this test contract with the governance asset so it can approve c
        // We use a low-level call to a faucet-like transferFrom from the asset itself is not possible;
        // instead we rely on the asset already being funded here. If not, the call below reverts which is fine.
        IERC20(asset).approve(address(c), amount);

        uint256 thisAfterApproval = IERC20(asset).balanceOf(address(this));

        bool reverted;
        try c.assertGovernanceApproved(address(this), target, false) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cAfter = IERC20(asset).balanceOf(address(c));
        uint256 thisAfter = IERC20(asset).balanceOf(address(this));

        // Conservation: the governance asset is only moved from this to c, so the sum is invariant.
        // If the call reverted, no tokens should have moved (transferFrom reverted atomically).
        // If succeeded, this decreased by exactly amount and c increased by exactly amount.
        assert(thisBefore + cBefore == thisAfter + cAfter);
    }

    receive() external payable {}
}

