        bool emergency
    ) public payable {
        require(address(this).balance >= 0);

        // Configure flash governance and security parameters; both require a successful proposal,
        // so call them and ignore revert outcomes (only assert in the success path below).
        bool configOk;
        try c.configureFlashGovernance(asset, flashAmount, unlockTime, assetBurnable) {
            configOk = true;
        } catch {
            configOk = false;
        }

        bool secOk;
        try c.configureSecurityParameters(1, epochSize, 0) {
            secOk = true;
        } catch {
            secOk = false;
        }

        // Give this test contract enough allowance so the transferFrom inside
        // assertGovernanceApproved can succeed. approve is a normal external call on a token.
        bool approved;
        try IERC20(asset).approve(address(c), approveAmount) returns (bool ok) {
            approved = ok;
        } catch {
            approved = false;
        }

        uint256 balanceBefore = IERC20(asset).balanceOf(address(this));
        uint256 cAssetBefore = IERC20(asset).balanceOf(address(c));

        (, uint256 lastActBefore, , ) = c.security();

        bool reverted;
        try c.assertGovernanceApproved(target, address(this), emergency) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (, uint256 lastActAfter, , ) = c.security();
        (uint256 pAmount, uint256 pUnlock, address pAsset, bool pBurnable) = c.pendingFlashDecision(target, address(this));

        if (configOk && secOk && approved) {
            if (reverted) {
                // If the pull failed or the decision slot was already unexpired, nothing should be recorded.
                assert(lastActAfter == lastActBefore && pAmount == 0 && pAsset == address(0));
            } else {
                assert(
                    pAmount == flashAmount &&
                    pAsset == asset &&
                    pBurnable == assetBurnable &&
                    pUnlock > block.timestamp &&
                    lastActAfter == block.timestamp &&
                    IERC20(asset).balanceOf(address(c)) == cAssetBefore + flashAmount
                );
            }
        }
    }

    receive() external payable {}
