    }

    function run(
        address asset,
        uint256 amount,
        uint256 unlockTime,
        address target,
        address user,
        uint256 burnAmount
    ) public payable {
        // Setup: configure flash governance with a non-burnable asset.
        // This call requires onlySuccessfulProposal; if it succeeds, it sets the config.
        c.configureFlashGovernance(asset, amount, unlockTime, false);

        // Setup: attempt to record a pending decision. If the pull succeeds and the
        // slot is unlocked, a pending decision is stored for (target, sender).
        // If it reverts, the slot remains empty.
        bool approved;
        try c.assertGovernanceApproved(target, address(this), true) {
            approved = true;
        } catch {
            approved = false;
        }

        // Read the pending decision before the burn attempt.
        (uint256 preAmount, uint256 preUnlock, address preAsset, bool preBurnable) = c.pendingFlashDecision(target, user);

        // Deciding call: burn (attempt) the governance asset for (target, user).
        // Requires onlySuccessfulProposal; if it succeeds it deletes the pending decision
        // (and for assetBurnable == false it should not call burn on the asset).
        c.burnFlashGovernanceAsset(target, user, asset, burnAmount);

        // Read the pending decision after the burn attempt.
        (uint256 postAmount, uint256 postUnlock, address postAsset, bool postBurnable) = c.pendingFlashDecision(target, user);

        // General rule: after burnFlashGovernanceAsset, the pending flash decision for
        // (target, user) is cleared whenever the setup produced a matching entry, and the
        // entry is always zeroed/deleted. The observation is expressed over public getters,
        // and we guard with the pre-state so the rule holds even if setup didn't record.
        assert(
            (preAmount == 0 && preAsset == address(0)) ||
            (postAmount == 0 && postUnlock == 0 && postAsset == address(0) && postBurnable == false)
        );
    }

    receive() external payable {}
}
